//! 🧪️ SVG paint publication preserves the neutral binary32 color contract.
use super::*;
#[test]fn rgba_percentage_attributes_preserve_all_source_channels(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let slot=row["slot"].as_str().unwrap();let color=row["color"].as_array().map(|values|std::array::from_fn(|at|values[at].as_f64().unwrap()as f32));let actual=attributes(slot,color).unwrap().to_string();if let Some(color)=color{assert!(actual.starts_with(&format!("{slot}=\"rgb(")));let inside=actual.split("rgb(").nth(1).unwrap().split(')').next().unwrap();let values:Vec<f32>=inside.split(',').map(|part|(part.strip_suffix('%').unwrap().parse::<f64>().unwrap()/100.0)as f32).collect();for at in 0..3{assert_eq!(values[at].to_bits(),color[at].clamp(0.0,1.0).to_bits(),"{} channel={at}",row["id"]);}let opacity=actual.rsplit('"').nth(1).unwrap().parse::<f32>().unwrap();assert_eq!(opacity.to_bits(),color[3].clamp(0.0,1.0).to_bits());}else{assert_eq!(actual,format!("{slot}=\"none\""));}}for bad in [f32::NAN,f32::INFINITY,f32::NEG_INFINITY]{assert!(attributes("fill",Some([bad,0.0,0.0,1.0])).is_err());}assert!(attributes("opacity",None).is_err());}
